/* ==========================================================
   MoodTube theme: Clear Case Red Stars  (theme format v2)
   A clear plastic disc case (picture in images.cover) over the track
   cover, which is cut to a disc and spins while music plays.
   Black and white. In a big window: text on the left, the case on the
   right, controls underneath. Smaller windows fall back to a column.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&family=Rubik+Mono+One&display=swap');

@keyframes cc-spin { to { transform: rotate(360deg); } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --cc-black: #000000;
    --cc-white: #f4f4f5;
    --cc-dim:   #8e9096;
    --cc-line:  rgba(255, 255, 255, 0.2);
    --cc-glass: rgba(255, 255, 255, 0.07);
    /* variants change these: accent colour, how the track cover is tinted, and a print laid over it */
    --cc-accent: #b9babd;
    --cc-cover-filter: grayscale(1) contrast(1.08) brightness(1.15);
    --cc-print: none;
    --cc-print-blend: normal;
    --cc-print-opacity: 1;
    --cc-print-spin: cc-spin 8s linear infinite;
    --mt-text: var(--cc-white);
    --mt-text-dim: var(--cc-dim);
    --mt-text-on-accent: #000000;
}

/* ---------- Sliders ---------- */
.mt-progress {
    --mt-slider-track: rgba(255, 255, 255, 0.22);
    --mt-slider-track-height: 4px;
    --mt-slider-track-radius: 2px;
    --mt-slider-thumb-size: 12px;
    --mt-slider-thumb-bg: #d4d4d6;
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--cc-accent);
}
.mt-volume {
    --mt-slider-track: rgba(255, 255, 255, 0.22);
    --mt-slider-track-height: 3px;
    --mt-slider-track-radius: 2px;
    --mt-slider-thumb-size: 9px;
    --mt-slider-thumb-bg: #d4d4d6;
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--cc-accent);
}

/* ---------- Window ---------- */
.mt-player {
    container-type: size;
    padding: 34px 18px 16px;
    background: var(--cc-black);
    border: 1px solid var(--cc-line);
    border-radius: 14px;
    color: var(--cc-white);
    font-family: 'Inter', 'Segoe UI', Arial, sans-serif;
    box-shadow: none;
    backdrop-filter: none; -webkit-backdrop-filter: none;
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

/* ---------- Header ---------- */
.mt-player-header { top: 13px; left: 18px; right: 96px; align-items: center; }
.mt-player-header-title { color: var(--cc-white); font-size: 10px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; }
.mt-player-status { color: var(--cc-dim); opacity: 1; font-size: 10px; letter-spacing: 0.06em; }
.mt-window-btn {
    top: 10px; width: 20px; height: 20px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 10px; color: var(--cc-dim); background: transparent; border: none;
}
.mt-window-btn:hover { color: #ffffff; }
.mt-btn-search { right: 62px; }
.mt-btn-settings { right: 38px; }
.mt-btn-close { right: 14px; }
.mt-resize-handle i { color: rgba(255, 255, 255, 0.3); }

/* ---------- The case and the disc ---------- */
.mt-player .mt-player-body { gap: 8px; }
.mt-cover {
    width: max(90px, min(78cqw, calc(100cqh - 125px), 300px)); height: max(90px, min(78cqw, calc(100cqh - 125px), 300px));
    border: none; border-radius: 0; background: transparent; box-shadow: none; overflow: visible;
}
/* the case picture sits over the disc */
.mt-cover .mt-slot-cover { background-size: contain; border-radius: 0; }
/* the track cover becomes the disc print: cut to the disc in the picture, clear hub in the middle */
.mt-cover-img {
    position: absolute; left: 8.8%; top: 7.2%; width: 81.2%; height: 81.2%;
    border-radius: 50%; object-fit: cover; background: #1a1c20;
    filter: var(--cc-cover-filter);
    -webkit-mask: radial-gradient(circle closest-side, transparent 0 28%, #000 29%);
    mask: radial-gradient(circle closest-side, transparent 0 28%, #000 29%);
}
.mt-player.mt-is-playing .mt-cover-img { animation: cc-spin 8s linear infinite; }
/* print over the disc (variants): same circle, under the case */
.mt-cover::after {
    content: ''; position: absolute; left: 8.8%; top: 7.2%; width: 81.2%; height: 81.2%; z-index: 1;
    border-radius: 50%; pointer-events: none;
    background: var(--cc-print); mix-blend-mode: var(--cc-print-blend); opacity: var(--cc-print-opacity);
    -webkit-mask: radial-gradient(circle closest-side, transparent 0 28%, #000 29%);
    mask: radial-gradient(circle closest-side, transparent 0 28%, #000 29%);
}
.mt-player.mt-is-playing .mt-cover::after { animation: var(--cc-print-spin); }
.mt-cover-hole { display: none; }

/* ---------- Track ---------- */
.mt-track-title { color: #ffffff; font-size: 14px; font-weight: 800; letter-spacing: -0.01em; margin-bottom: 1px; }
.mt-track-subtitle { color: var(--cc-dim); font-size: 11px; font-weight: 400; font-style: italic; }
.mt-btn-favorite { color: var(--cc-dim); font-size: 13px; }
.mt-btn-favorite:hover { color: #ffffff; }
.mt-btn-favorite.mt-is-active { color: var(--cc-heart, #ffffff); }

/* ---------- Progress ---------- */
.mt-progress { margin-top: 0; }
.mt-time { color: var(--cc-dim); font-size: 10px; font-weight: 600; }
.mt-time-current { color: #ffffff; }

/* ---------- Buttons: plain white icons ---------- */
.mt-controls { gap: 16px; }
.mt-controls > .mt-btn { font-size: 13px; color: var(--cc-dim); background: none; }
.mt-controls > .mt-btn-prev, .mt-controls > .mt-btn-next { color: #ffffff; font-size: 15px; }
.mt-controls > .mt-btn-play { width: 24px; font-size: 22px; color: #ffffff; }
.mt-controls > .mt-btn:hover { transform: none; color: #ffffff; }
.mt-btn-ai.mt-is-busy { color: #ffffff; }
.mt-volume-icon { color: var(--cc-dim); font-size: 10px; }

/* ---------- Wide bar ---------- */
.mt-player.moodtube-row-layout .mt-player-body { gap: 10px; }
.mt-player.moodtube-row-layout .mt-cover { width: 54px; height: 54px; }
.mt-player.moodtube-row-layout .mt-track-info { flex: 1 1 100px; min-width: 60px; padding-right: 20px; }
.mt-player.moodtube-row-layout .mt-track-title { font-size: 12px; }
.mt-player.moodtube-row-layout .mt-time-total { display: none; }
.mt-player.moodtube-row-layout .mt-progress { flex: 1 1 100px; min-width: 80px; }
.mt-player.moodtube-row-layout .mt-controls { gap: 10px; }
.mt-player.moodtube-row-layout .mt-volume { flex: 0 1 70px; min-width: 48px; }
.mt-player.moodtube-row-layout .mt-volume-high { display: none; }

/* ---------- Big window (also a wide one that is tall enough): text left, case right ---------- */
@container (min-width: 380px) and (min-height: 180px) {
    #moodtube-mini-player .mt-player-body {
        display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: minmax(0, 1fr) auto auto;
        column-gap: 18px; row-gap: 10px; align-items: center; justify-items: stretch; padding: 0 4px;
    }
    #moodtube-mini-player .mt-cover {
        grid-column: 2; grid-row: 1; justify-self: end;
        width: min(calc(100cqh - 62px), 52cqw, 340px); height: min(calc(100cqh - 62px), 52cqw, 340px);
    }
    #moodtube-mini-player .mt-track-info {
        grid-column: 1; grid-row: 1; align-self: center; width: auto; min-width: 0;
        align-items: flex-start; text-align: left; padding: 0 26px 0 0;
    }
    #moodtube-mini-player .mt-track-info > span { white-space: normal; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; }
    #moodtube-mini-player .mt-track-title { font-size: clamp(16px, 5cqw, 30px); line-height: 1.15; margin-bottom: 6px; }
    #moodtube-mini-player .mt-track-subtitle { font-size: clamp(11px, 2.6cqw, 16px); -webkit-line-clamp: 1; }
    #moodtube-mini-player .mt-btn-favorite { top: 2px; }
    #moodtube-mini-player .mt-controls { grid-column: 1; grid-row: 2; justify-self: start; gap: 18px; }
    #moodtube-mini-player .mt-volume { grid-column: 2; grid-row: 2; justify-self: end; width: 130px; min-width: 0; }
    #moodtube-mini-player .mt-volume-high { display: inline-block; }
    #moodtube-mini-player .mt-progress { grid-column: 1 / -1; grid-row: 3; width: auto; min-width: 0; }
    #moodtube-mini-player .mt-time-total { display: inline; }
}

/* ---------- Queue / playlists ---------- */
.mt-panel { background: rgba(0, 0, 0, 0.96); padding-top: 40px; border-radius: inherit; }
.mt-panel-title { color: var(--cc-white); font-size: 10px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--cc-white); }
.mt-queue-item { background: var(--cc-glass); border-color: rgba(255, 255, 255, 0.1); border-radius: 8px; }
.mt-queue-item:hover { background: rgba(255, 255, 255, 0.12); }
.mt-queue-item.mt-is-current { background: rgba(255, 255, 255, 0.1); border-color: var(--cc-white); }
.mt-queue-thumb { border-radius: 50%; filter: grayscale(1); }
.mt-queue-thumb.mt-is-empty { background: rgba(255, 255, 255, 0.14); }
.mt-queue-title { color: var(--cc-dim); font-size: 11px; }
.mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: #ffffff; }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #e9707a; }
.mt-queue-now, .mt-queue-add { color: var(--cc-white); }
.mt-queue-dislike { background-color: var(--cc-white); }
.mt-queue-empty { color: var(--cc-dim); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
    background: var(--cc-black); border-color: rgba(255, 255, 255, 0.5); box-shadow: none; color: var(--cc-white);
}

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: rgba(255, 255, 255, 0.35) transparent; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 6px; height: 6px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: transparent; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.35); border-radius: 3px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(0, 0, 0, 0.7);
    --mt-modal-shadow: none;
    --mt-text-strong: #ffffff;
    --mt-divider: rgba(255, 255, 255, 0.1);
}
#mt-settings-modal .mt-flex-container { border: 1px solid var(--cc-line); border-radius: 14px; }
#mt-settings-modal .mt-header h3 { font-size: 1em; letter-spacing: 0.18em; text-transform: uppercase; }
#mt-settings-modal .mt-close { color: var(--cc-white); }
#mt-settings-modal .mt-tag { background-color: var(--cc-glass); border-color: var(--cc-line); box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: rgba(255, 255, 255, 0.14); border-color: var(--cc-white);
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--cc-white); border-color: var(--cc-white); box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: var(--cc-glass); border-color: var(--cc-line); }
#mt-settings-modal .mt-btn-test:hover { background: rgba(255, 255, 255, 0.14); border-color: var(--cc-white); }
#mt-settings-modal .mt-subpanel { background: rgba(255, 255, 255, 0.04); }

/* ---------- Search panel and playlists ---------- */
.mt-panel-search { --mt-bg-primary: #000000; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #000000) !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--cc-white); --mt-pl-spotify-tab-text: #000000; }
.mt-pl-tabs { background: var(--cc-glass); border: 1px solid rgba(255, 255, 255, 0.1); }
.mt-pl-tool { background: var(--cc-glass); border-color: var(--cc-line); color: var(--cc-white); }
.mt-pl-tool:hover { background: rgba(255, 255, 255, 0.14); }
.mt-pl-tool.mt-pl-play { background: var(--cc-white); border-color: var(--cc-white); color: #000000; }
.mt-pl-inline-cancel { background: var(--cc-glass); color: var(--cc-white); }
.mt-pl-cover-empty { background: rgba(255, 255, 255, 0.1); color: var(--cc-dim); }
.mt-pl-modal { --mt-overlay: rgba(0, 0, 0, 0.7); }
.mt-pl-modal-box { background: var(--cc-black); border: 1px solid var(--cc-line); border-radius: 14px; }
.mt-pl-modal-track { border-bottom-color: rgba(255, 255, 255, 0.1); }
.mt-pl-option { background: var(--cc-glass); }
.mt-pl-option:hover { background: rgba(255, 255, 255, 0.14); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--cc-white); }

@container (max-width: 300px) { .mt-player .mt-player-status { display: none; } }

/* ========== Variant: Clear Case Red Stars ========== */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
